/**
 * city-sensors.ts — the city page's mock sensors, typed, plus the pure helpers the map and the
 * cards share (freshness, nearest reporting sensors, distance and age in words).
 *
 * Purpose
 *   One sensor file per city page (./sensors/[city]-page.json, generated by
 *   ./generators/gen_bogota_page_sensors.py), validated here so the map, the tap card, the sensor
 *   detail and the city section's tiles all read the SAME sensors and can never disagree.
 *
 * Nothing here interprets air quality (spec section 2)
 *   - Bands come from the file, as "the city's feed publishes them". Nothing converts a reading to a
 *     band, averages sensors, or gives a value to a place with no sensor (rule 1).
 *   - The nearest-three helper only SORTS sensors by distance. It never combines their readings.
 *   - Freshness is a statement about time since the last reading, against the city's own update
 *     cycle (`updateCycleMinutes` in the city's data file, spec 5.5), not about air quality.
 *
 * Freshness (iteration 4, round 3 decision B1: two states only, no dead state)
 *   fresh  within the city's cycle   full treatment, the city's band colour, "12 min ago"
 *   stale  older, however old        grey, no band, no scale marker, no advice, age in words
 *                                    ("Last reading 9 hours ago", "Last reading 6 days ago")
 *   Nothing drops out: a stale sensor stays on the map and can be one of the nearest three.
 *
 * Fresh reading, no band (iteration 4, decision B2)
 *   `overallBand` (and a reading's `band`) can be null: the city sent a fresh reading but no band
 *   (Bogotá's "SIN DATOS"). The page never fills that gap: no colour, no scale marker, no advice.
 *   The band ALWAYS comes from the city's feed; nothing here or anywhere computes one.
 *
 * Mock data (READ BEFORE EDITING)
 *   Positions and sensor types come from the Atlas's snapshot file; readings, bands, freshness and
 *   station types are INVENTED (see the generator). The nav's "Prototype with sample data" notice
 *   covers them. Iteration 2 (decision C2): real stations carry RMCAB's own station name; placed
 *   low-cost sensors carry the locality their mock position falls in (mock). placeName() says which.
 *
 * Key exports: PollutantId, SensorType, Freshness, SensorReading, CitySensor, POLLUTANT_ORDER,
 *   parseCitySensors, freshnessOf, distanceKm, nearestReporting, distanceWords, ageWords,
 *   sensorTypeLabel, sensorTypeCardLabel, placeName
 * External dependencies: none (the caller passes the JSON in).
 */

/**
 * Every pollutant any of the five cities publishes in its station data (round 3 decision X:
 * "we show the data that we get from the cities"), by its notation. Each city lists its own in
 * CityPage.publishedPollutants, from its <city>-pollutant-names.csv.
 */
export type PollutantId =
  | 'PM1' | 'PM2.5' | 'PM10' | 'TSP' | 'O₃' | 'NO₂' | 'NO' | 'NOₓ' | 'SO₂' | 'CO' | 'HC' | 'Black carbon'
  | 'Benzene' | 'H₂S' | 'CH₄' | 'NMHC' | 'THC' | 'NH₃' | 'As' | 'Cd' | 'Ni' | 'Pb' | 'BaP'

/** The order pollutants are listed in, everywhere (particles, the index gases, then the rest). */
export const POLLUTANT_ORDER: PollutantId[] = [
  'PM1', 'PM2.5', 'PM10', 'TSP', 'O₃', 'NO₂', 'NO', 'NOₓ', 'SO₂', 'CO', 'HC', 'Black carbon',
  'Benzene', 'H₂S', 'CH₄', 'NMHC', 'THC', 'NH₃', 'As', 'Cd', 'Ni', 'Pb', 'BaP',
]

/**
 * Each pollutant's English name, as the cities' own lists name it (translated). A name, not a
 * description: nothing here explains what a pollutant is or does (decision X: "we don't interpret it").
 */
export const POLLUTANT_NAMES: Record<PollutantId, string> = {
  PM1: 'Particulate matter PM1',
  'PM2.5': 'Fine particulate matter',
  PM10: 'Coarse particulate matter',
  TSP: 'Total suspended particulates',
  'O₃': 'Ozone',
  'NO₂': 'Nitrogen dioxide',
  NO: 'Nitrogen monoxide',
  'NOₓ': 'Nitrogen oxides',
  'SO₂': 'Sulfur dioxide',
  CO: 'Carbon monoxide',
  HC: 'Hydrocarbons',
  'Black carbon': 'Black carbon',
  Benzene: 'Benzene',
  'H₂S': 'Hydrogen sulfide',
  'CH₄': 'Methane',
  NMHC: 'Non-methane hydrocarbons',
  THC: 'Total hydrocarbons',
  'NH₃': 'Ammonia',
  As: 'Arsenic',
  Cd: 'Cadmium',
  Ni: 'Nickel',
  Pb: 'Lead',
  BaP: 'Benzo(a)pyrene',
}

/** Sensor type: circle on the map for low-cost, square for a reference monitor. */
export type SensorType = 'low-cost' | 'reference-grade'

/** Freshness state (iteration 4, decision B1): two states only. */
export type Freshness = 'fresh' | 'stale'

/** One pollutant reading at one sensor, as the city's feed publishes it (mock). */
export type SensorReading = {
  pollutant: PollutantId
  /** Raw value. Shown only in the sensor detail, never to residents on the card (rule 7). */
  value: number
  unit: string
  /** The averaging time the city publishes for this pollutant. Shown as data, never next to a band. */
  averaging: string
  /**
   * The city's band for this pollutant at this sensor, 1 = the index's best level, as the feed
   * publishes it. Null when the feed sent none (decision B2) or the city has no index (Sofia, Milan).
   */
  band: number | null
  /**
   * Minutes since THIS pollutant was read, only where it is older than the sensor's own update time
   * (iteration 4, decision D3: shown inside the row's "i"); null when it was read with the rest.
   */
  updatedMinutesAgo: number | null
}

/** One sensor on the city page. */
export type CitySensor = {
  id: string
  /** [longitude, latitude], Mapbox order. Never shown as numbers. */
  lngLat: [number, number]
  type: SensorType
  /** Station type where the city publishes one (reference monitors), translated; else null. */
  stationType: string | null
  /** The station's name as the city publishes it, or null (placed sensors have none). */
  name: string | null
  /** Where there is no name: the locality (such as the district) the sensor sits in, else null. */
  location: string | null
  /**
   * The station's overall level as the city's feed publishes it (spec 5.2). Null when the feed sent
   * a reading but no band (decision B2), or when the city rates areas or nothing, not stations.
   */
  overallBand: number | null
  /** Minutes since the last reading. */
  updatedMinutesAgo: number
  readings: SensorReading[]
}

/** Narrow a record, or throw. */
function asRecord(value: unknown, where: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new Error(`Breathe Data Atlas sensors: ${where} is not an object`)
  }
  return value as Record<string, unknown>
}

/** Narrow a finite number, or throw. */
function asNumber(value: unknown, where: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new Error(`Breathe Data Atlas sensors: ${where} is not a number`)
  }
  return value
}

/** Narrow a non-empty string, or throw. */
function asString(value: unknown, where: string): string {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`Breathe Data Atlas sensors: ${where} is not a string`)
  }
  return value
}

/** Narrow a pollutant id, or throw. */
function asPollutant(value: unknown, where: string): PollutantId {
  if (typeof value !== 'string' || !(POLLUTANT_ORDER as string[]).includes(value)) {
    throw new Error(`Breathe Data Atlas sensors: ${where} is not a known pollutant`)
  }
  return value as PollutantId
}

/**
 * Narrow one city's sensor file, or throw. `bandCount` is the city index's number of levels: a band
 * outside it would render a colour the city never published, so it fails the build instead.
 */
export function parseCitySensors(value: unknown, slug: string, bandCount: number): CitySensor[] {
  const file = asRecord(value, slug)
  if (file.city !== slug) {
    throw new Error(`Breathe Data Atlas sensors: file for "${slug}" says it is "${String(file.city)}"`)
  }
  if (!Array.isArray(file.sensors) || file.sensors.length === 0) {
    throw new Error(`Breathe Data Atlas sensors: ${slug} has no sensors`)
  }
  const checkBand = (raw: unknown, where: string): number | null => {
    if (raw === null || raw === undefined) return null
    const band = asNumber(raw, where)
    if (!Number.isInteger(band) || band < 1 || band > bandCount) {
      throw new Error(`Breathe Data Atlas sensors: ${where} band ${band} is outside the index`)
    }
    return band
  }
  return file.sensors.map((entry, position) => {
    const record = asRecord(entry, `${slug}.sensors[${position}]`)
    const id = asString(record.id, `${slug}.sensors[${position}].id`)
    const lngLat = record.lngLat
    if (!Array.isArray(lngLat) || lngLat.length !== 2) {
      throw new Error(`Breathe Data Atlas sensors: ${id}.lngLat is not a pair`)
    }
    if (record.type !== 'low-cost' && record.type !== 'reference-grade') {
      throw new Error(`Breathe Data Atlas sensors: ${id} has an unknown type`)
    }
    if (!Array.isArray(record.readings) || record.readings.length === 0) {
      throw new Error(`Breathe Data Atlas sensors: ${id} has no readings`)
    }
    const minutes = asNumber(record.updatedMinutesAgo, `${id}.updatedMinutesAgo`)
    if (minutes < 0) {
      throw new Error(`Breathe Data Atlas sensors: ${id}.updatedMinutesAgo is negative`)
    }
    const name = record.name === null || record.name === undefined ? null : asString(record.name, `${id}.name`)
    const location =
      record.location === null || record.location === undefined ? null : asString(record.location, `${id}.location`)
    if (name === null && location === null) {
      throw new Error(`Breathe Data Atlas sensors: ${id} has neither a name nor a location`)
    }
    return {
      id,
      name,
      location,
      lngLat: [asNumber(lngLat[0], `${id}.lngLat[0]`), asNumber(lngLat[1], `${id}.lngLat[1]`)],
      type: record.type,
      stationType: record.stationType === null ? null : asString(record.stationType, `${id}.stationType`),
      overallBand: checkBand(record.overallBand, `${id}.overallBand`),
      updatedMinutesAgo: minutes,
      readings: record.readings.map((reading, index) => {
        const r = asRecord(reading, `${id}.readings[${index}]`)
        return {
          pollutant: asPollutant(r.pollutant, `${id}.readings[${index}].pollutant`),
          value: asNumber(r.value, `${id}.readings[${index}].value`),
          unit: asString(r.unit, `${id}.readings[${index}].unit`),
          averaging: asString(r.averaging, `${id}.readings[${index}].averaging`),
          band: checkBand(r.band, `${id}.readings[${index}].band`),
          updatedMinutesAgo:
            r.updatedMinutesAgo === null || r.updatedMinutesAgo === undefined
              ? null
              : asNumber(r.updatedMinutesAgo, `${id}.readings[${index}].updatedMinutesAgo`),
        }
      }),
    }
  })
}

/** A sensor's freshness against the city's update cycle (decision B1). Pure. */
export function freshnessOf(sensor: CitySensor, updateCycleMinutes: number): Freshness {
  if (sensor.updatedMinutesAgo > updateCycleMinutes) return 'stale'
  return 'fresh'
}

/** Great-circle distance in km between two [lng, lat] points (haversine). Pure. */
export function distanceKm([lng1, lat1]: [number, number], [lng2, lat2]: [number, number]): number {
  const radius = 6371
  const dLat = ((lat2 - lat1) * Math.PI) / 180
  const dLng = ((lng2 - lng1) * Math.PI) / 180
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2
  return radius * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
}

/**
 * The `count` nearest sensors to a point, nearest first, fresh or stale (iteration 4, decision B1:
 * nothing drops out of the nearest three). `excludeId` leaves out the tapped sensor itself. Only
 * sorts; never combines readings (rule 1). Empty input returns an empty list.
 */
export function nearestReporting(
  point: [number, number],
  sensors: CitySensor[],
  count: number,
  excludeId: string | null,
  _updateCycleMinutes: number,
): Array<{ sensor: CitySensor; km: number }> {
  if (sensors.length === 0 || count <= 0) return []
  return sensors
    .filter((sensor) => sensor.id !== excludeId)
    .map((sensor) => ({ sensor, km: distanceKm(point, sensor.lngLat) }))
    .sort((a, b) => a.km - b.km)
    .slice(0, count)
}

/** A distance in words for the card: "450 m", "1.2 km", "12 km". Pure. */
export function distanceWords(km: number): string {
  if (km < 1) return `${Math.max(10, Math.round((km * 1000) / 10) * 10)} m`
  if (km < 10) return `${km.toFixed(1)} km`
  return `${Math.round(km)} km`
}

/** Time since a reading, in words: "12 min ago", "9 hours ago", "6 days ago". Pure. */
export function ageWords(minutes: number): string {
  if (minutes < 60) return `${Math.max(1, Math.round(minutes))} min ago`
  const hours = Math.round(minutes / 60)
  if (hours < 24) return hours === 1 ? '1 hour ago' : `${hours} hours ago`
  const days = Math.round(hours / 24)
  return days === 1 ? '1 day ago' : `${days} days ago`
}

/**
 * What the card and the detail call a sensor (decision C2): its station name, or "In [locality]"
 * where it has no name, so a place is never mistaken for a station name. Pure.
 */
export function placeName(sensor: CitySensor): string {
  if (sensor.name !== null) return sensor.name
  return `In ${sensor.location ?? 'an unnamed place'}`
}

/**
 * The sensor type as the sensor card and detail name it. Iteration 3 (round 2 decision B): the
 * same OpenAQ names as everywhere else, so this now matches sensorTypeLabel.
 */
export function sensorTypeCardLabel(type: SensorType): string {
  return sensorTypeLabel(type)
}

/**
 * The sensor type as the page names it (legend, tiles, card, detail, pop-up). Iteration 3 (round 2
 * decision B): OpenAQ's names, "Reference grade" and "Low-cost sensor".
 */
export function sensorTypeLabel(type: SensorType): string {
  return type === 'reference-grade' ? 'Reference grade' : 'Low-cost sensor'
}
